UPDATE locales SET events = json_patch(events, '{"wife_dog_park":{"title":"Собака для жены","desc":"Жена хочет собаку, но в районе нет площадки для выгула.","choices":["🐕 Сделать через друга: отдать постройку вольеров своему человеку и получить породистую собаку, ваучер на корм и дрессировщика","🏗️ Провести нормальный публичный тендер на площадку для выгула","🙅 Отказать: собака — слишком большая ответственность и вообще «не её тема»"]},"cat_exhibition":{"title":"Выставка кошек","desc":"Жена познакомилась с местным клубом любителей кошек и просит организовать городскую выставку.","choices":["🐈 Отдать организацию другу-промоутеру за откат","📋 Выделить бюджет и провести открытый конкурс","🤧 Заявить, что у мэра аллергия на шерсть, и свернуть тему"]},"lgbt_parade":{"title":"Парад Гордости на улице Вайцман","desc":"Организаторы просят разрешение провести Парад Гордости на центральной улице города. Тема вызвала бурные споры.","choices":["🏳️‍🌈 Разрешить на Вайцман! Спонсоры отблагодарят, а прогрессивные жители в восторге","🎪 Выделить закрытую площадку в промзоне, чтобы не смущать религиозных","🚫 Заявить «Я стрейт, никаких парадов не будет!»"]},"lgbt_coalition_crisis":{"title":"Кризис в коалиции","desc":"Религиозные партнеры по коалиции в бешенстве от прошедшего парада и требуют немедленно закрыть городской ЛГБТ-клуб.","choices":["🔒 Закрыть клуб и уступить требованиям коалиции","🚚 Перенести клуб в Эйзор Таасия (промзону) за счет бюджета","🏢 Открыть второй клуб прямо в центре религиозного района (организаторы занесут денег)"]},"mayors_strip_club":{"title":"Скандал после встречи мэров","desc":"После ежегодного съезда мэров вы пошли отмечать в стрип-клуб. Пресса узнала об этом и устроила вам головомойку.","choices":["🙈 Уйти в несознанку: «Меня там не было, это монтаж!»","⚖️ Нанять топ-адвоката, чтобы заставить журналистов всё замять","📸 Слить прессе компрометирующие фото других мэров с той вечеринки"]},"mayors_revenge":{"title":"Ответка союза мэров","desc":"Мэры соседних городов узнали, кто слил их фотографии в стрип-клубе прессе, и решили объединиться против вас.","choices":["💸 Выплатить компенсацию в их межмуниципальный фонд","🛡️ Игнорировать их угрозы и заблокировать совместные городские проекты","🎉 Устроить грандиозную закрытую «примирительную» вечеринку с шикарным фуршетом"]},"son_wedding":{"title":"Свадьба сына","desc":"Ваш сын женится. Это отличное событие и поворотный момент для всей семьи.","choices":["🏰 Организовать пышную свадьбу: прикрытие для встреч с нужными людьми и сбор конвертов","🕊️ Пусть дети организуют всё сами, город не вмешивается","🥂 Сделать скромный праздник только для близких родственников за свой счет"]},"wedding_investigation":{"title":"Расследование по свадьбе","desc":"Журналисты пронюхали, что на пышной свадьбе сына вам передавали взятки под видом подарков.","choices":["🤝 Нанять «решалу» для работы с редакцией","🔥 Поджечь типографию/редакцию газеты","🙈 Игнорировать расследование и заявить, что это наветы"]},"father_funeral":{"title":"Траур и похороны отца","desc":"В семье stem-трагедия: скончался ваш отец. Время проведения шивы и приема соболезнований.","choices":["🕯️ Принимать на шиве важных людей: у вас горе, полиция не лезет, а вопросы решаются","👥 Принять коллег и родственников без коммерческих разговоров","🔒 Скрыть шиву, пустить только самых близких"]},"father_monument_offer":{"title":"Памятник от застройщиков","desc":"Влиятельные застройщики, приходившие на шиву, предлагают полностью оплатить элитный памятник вашему отцу.","choices":["🪦 Принять предложение: у отца должен быть самый большой памятник на кладбище","📐 Принять помощь, но сделать скромный и умеренный памятник","🚫 Отказать и возвести памятник полностью за свой счет"]},"daughter_school":{"title":"Дочка идет в школу","desc":"Формирование классов на новый учебный год. Пора решить, с кем будет учиться ваша дочь.","choices":["🏫 Посадить в класс с детьми нужных людей и бизнесменов","🎒 Обычный класс: у нас все дети и родители равны","🎓 Отправить в закрытую частную школу"]},"school_flood":{"title":"Потоп в школе","desc":"В школе дочери прорвало старые трубы, классы полностью затоплены.","choices":["🤝 Нужные родители из класса всё быстро починят сами и занесут на ремонт","🏗️ Муниципальный ремонт через тендер (школа закрыта на месяц)","🛠️ Починить всё немедленно за свои деньги"]}}') WHERE lang = 'ru';

UPDATE locales SET events = json_patch(events, '{"wife_dog_park":{"title":"A Dog for the Wife","desc":"Your wife wants a dog, but there is no dog park in the neighborhood.","choices":["🐕 Do it through a friend: give the kennel construction to your man and get a pedigree dog, food voucher and trainer","🏗️ Hold a proper public tender for the dog park","🙅 Refuse: a dog is too much responsibility and simply «not her thing»"]},"cat_exhibition":{"title":"Cat Exhibition","desc":"Your wife met a local cat-lovers club and asks you to organize a city exhibition.","choices":["🐈 Give the organization to a promoter friend for a kickback","📋 Allocate a budget and hold an open competition","🤧 Claim the mayor is allergic to fur and shut the idea down"]},"lgbt_parade":{"title":"Pride Parade on Weizmann Street","desc":"Organizers ask permission to hold a Pride Parade on the city''s central street. The issue has caused fierce debate.","choices":["🏳️‍🌈 Allow it on Weizmann! Sponsors will thank you and progressives will be thrilled","🎪 Allocate a closed venue in the industrial zone to avoid upsetting the religious","🚫 Declare: «I am straight, there will be no parade!»"]},"lgbt_coalition_crisis":{"title":"Coalition Crisis","desc":"Your religious coalition partners are furious about the parade and demand the city''s LGBT club close immediately.","choices":["🔒 Close the club and give in to the coalition","🚚 Move the club to the industrial zone at the city''s expense","🏢 Open a second club in the heart of a religious neighborhood (the organizers will pay well)"]},"mayors_strip_club":{"title":"Scandal after the Mayors'' Meeting","desc":"After the annual mayors'' convention, you went to celebrate at a strip club. The press found out and gave you a public beating.","choices":["🙈 Deny everything: «I was never there, it is a montage!»","⚖️ Hire a top lawyer to force the journalists to bury the story","📸 Leak compromising photos of the other mayors from that party"]},"mayors_revenge":{"title":"The Mayors'' Alliance Strikes Back","desc":"Mayors from neighboring cities discovered who leaked their strip-club photos to the press and decided to unite against you.","choices":["💸 Pay compensation into their inter-municipal fund","🛡️ Ignore their threats and block joint city projects","🎉 Throw a grand private reconciliation party with an extravagant buffet"]},"son_wedding":{"title":"Son''s Wedding","desc":"Your son is getting married. It is an excellent event and a turning point for the whole family.","choices":["🏰 Organize a lavish wedding: a cover for meetings with the right people and collecting envelopes","🕊️ Let the children organize everything themselves; the city stays out of it","🥂 Hold a modest celebration for close relatives at your own expense"]},"wedding_investigation":{"title":"Wedding Investigation","desc":"Journalists discovered that bribes were handed to you as gifts at your son''s lavish wedding.","choices":["🤝 Hire a fixer to deal with the editorial office","🔥 Set fire to the newspaper''s print shop/editorial office","🙈 Ignore the investigation and claim it is slander"]},"father_funeral":{"title":"Mourning and Father''s Funeral","desc":"A family tragedy: your father has died. It is time for shiva and receiving condolences.","choices":["🕯️ Receive important people at shiva: you are grieving, police stay away, and business gets done","👥 Receive colleagues and relatives without business talk","🔒 Keep shiva private and allow only the closest family"]},"father_monument_offer":{"title":"Monument from Developers","desc":"Influential developers who visited the shiva offer to pay for an elite monument for your father.","choices":["🪦 Accept: your father deserves the biggest monument in the cemetery","📐 Accept the help, but build a modest and moderate monument","🚫 Refuse and build the monument entirely at your own expense"]},"daughter_school":{"title":"Daughter Starts School","desc":"Classes are being formed for the new school year. It is time to decide who your daughter will study with.","choices":["🏫 Put her in a class with the children of important people and businessmen","🎒 A regular class: all children and parents are equal here","🎓 Send her to an exclusive private school"]},"school_flood":{"title":"School Flood","desc":"Old pipes burst at your daughter''s school, completely flooding the classrooms.","choices":["🤝 The important parents from the class will fix everything quickly and donate to the repairs","🏗️ Use a municipal tender for repairs (the school closes for a month)","🛠️ Fix everything immediately with your own money"]}}') WHERE lang = 'en';

UPDATE locales SET events = json_patch(events, '{"wife_dog_park":{"title":"כלב לאישה","desc":"אשתך רוצה כלב, אבל בשכונה אין גינת כלבים.","choices":["🐕 לסדר דרך חבר: למסור לו את בניית המתחם ולקבל כלב גזעי, שובר למזון ומאלף","🏗️ לערוך מכרז ציבורי מסודר לגינת הכלבים","🙅 לסרב: כלב הוא אחריות גדולה מדי וזה פשוט «לא בשבילה»"]},"cat_exhibition":{"title":"תערוכת חתולים","desc":"אשתך הכירה מועדון מקומי של חובבי חתולים ומבקשת לארגן תערוכה עירונית.","choices":["🐈 למסור את הארגון למפיק חבר תמורת שוחד","📋 להקצות תקציב ולערוך תחרות פתוחה","🤧 לטעון שלראש העיר יש אלרגיה לפרווה ולסגור את הנושא"]},"lgbt_parade":{"title":"מצעד הגאווה ברחוב וייצמן","desc":"המארגנים מבקשים אישור לקים את מצעד הגאווה ברחוב המרכזי. הנושא מחולל סערה בעיר.","choices":["🏳️‍🌈 לאשר בוייצמן! הספונסרים יודו לך והתושבים הליברלים בעננים","🎪 להקצות מתחם סגור באזור התעשייה כדי לא לפגוע ברגשות הדתיים","🚫 להצהיר ''אני סטרייט, לא יהיו כאן מצעדים!''"]},"lgbt_coalition_crisis":{"title":"משבר בקואליציה","desc":"השותפים הדתיים בקואליציה זועמים על המצעד ודורשים לסגור מיידית את מועדון הקהילה בעיר.","choices":["🔒 לסגור את המועדון ולהיכנע לתרגיל הקואליציוני","🚚 להעביר את המועדון לאזור התעשייה על חשבון העירייה","🏢 לפתוח מועדון נוסף בלב השכונה הדתית (המארגנים ישלמו יפה)"]},"mayors_strip_club":{"title":"סערת מועדון החשפנות","desc":"אחרי כנס ראשי הערים הלכתם לחגוג במועדון חשפנות. התקשורת גילתה וחוגגת על החשבון.","choices":["🙈 להכחיש הכל: ''זה לא אני, תמונה מעובדת!''","⚖️ לשכור עורך דין צמרת שיסגור את הסיפור מול הכתבים","📸 להדליף לתקשורת תמונות מביכות של ראשי ערים אחרים מהאירוע"]},"mayors_revenge":{"title":"נקמת ראשי הערים","desc":"ראשי הערים השכנות גילו שאתה זה שהדליף את התמונות שלהם לתקשורת, והחליטו לאחד כוחות נגדך.","choices":["💸 לשלם פיצויים לקרן המשותפת של הרשויות","🛡️ להתעלם מהאיומים ולחסום פרויקטים עירוניים משותפים","🎉 לארגן מסיבת פיוס סגורה ומפוארת עם כיבוד עשיר"]},"son_wedding":{"title":"חתונת הבן","desc":"הבן שלך מתחתן. אירוע מרגש ונקודת ציון חשובה לכל המשפחה.","choices":["🏰 לארגן חתונה מפוארת: כיסוי מעולה לפגישות אנשי שלומנו ואיסוף מעטפות","🕊️ שהילדים יארגנו הכל לבד, העירייה לא מתערבת","🥂 אירוע צנוע לבני משפחה קרובים בלבד על חשבונך הפרטי"]},"wedding_investigation":{"title":"תחקיר החתונה","desc":"עיתונאים גילו שבחסות החתונה המפוארת של הבן הועברו אליך שוחד ומעטפות מאינטרסנטים.","choices":["🤝 לשכור ''מאכער'' שיסגור עניין מול המערכת","🔥 להצית את בית הדפוס / מערכת העיתון","🙈 להתעלם מהתחקיר ולטעון שמדובר ברדיפה"]},"father_funeral":{"title":"שבעה והלוויית האב","desc":"טרגדיה במשפחה: אביך הלך לעולמו. זמן לשבעה וקבלת מנחמים.","choices":["🕯️ לקבל אנשים חשובים בשבעה: כולם מתחשבים באבל והעניינים זורמים","👥 לקבל קולגות וקרובים ללא שיחות ביזנס","🔒 לסגור את השבעה למשפחה גרעינית בלבד"]},"father_monument_offer":{"title":"מצבה מהיזמים","desc":"יזמים חזקים שהגיעו לנחם מציעים לממן מכיסם מצבה מפוארת ויוקרתית לאביך.","choices":["🪦 לקבל את ההצעה: לאבא מגיעה המצבה הכי גדולה בבית העלמין","📐 לקבל עזרה, אך להקים מצבה צנועה ומכובדת","🚫 לסרב ולהקים מצבה מכיסך הפרטי בלבד"]},"daughter_school":{"title":"הבת עולה לכיתה א''","desc":"שיבוץ הכיתות לשנת הלימודים. הגיע הזמן להחליט עם מי תלמד הבת שלך.","choices":["🏫 לשבץ אותה בכיתה עם הילדים של האנשים הנכונים והאנשי עסקים","🎒 כיתה רגילה: אצלנו כל הילדים וההורים שווים","🎓 לרשום אותה לבית ספר פרטי ויוקרתי"]},"school_flood":{"title":"הצפה בבית הספר","desc":"צינור ראשי התפוצץ בבית הספר של הבת, הכיתות מוצפות לחלוטין.","choices":["🤝 ההורים הנכונים מהכיתה יפתרו הכל במהירות ויביאו תרומה","🏗️ שיפוץ עירוני דרך מכרז (בית הספר ייסגר לחודש)","🛠️ לתקן הכל מיידית מכיסך הפרטי"]}}') WHERE lang = 'he';

COMMIT;
